<?php
$step=(int)($_GET['step']??1);$error=null;$data=$_SESSION['install']??[];
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$step=(int)($_POST['step']??1);$data=array_merge($data,$_POST);$_SESSION['install']=$data;if($step<4){header('Location: '.url('/?step='.($step+1)));exit;}
$name=trim($data['site_name']??'GameScore');$host=trim($data['db_host']??'localhost');$dbn=trim($data['db_name']??'gamescore');$dbu=trim($data['db_user']??'');$dbp=$data['db_pass']??'';$dsn='mysql:host='.$host.';dbname='.$dbn.';charset=utf8mb4';try{$pdo=new PDO($dsn,$dbu,$dbp,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$schema=file_get_contents(APP_ROOT.'/database/schema.sql');$pdo->exec($schema);$email=strtolower(trim($data['admin_email']??''));$pass=$data['admin_pass']??'';$s=$pdo->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,"admin")');$s->execute([trim($data['admin_name']??'Admin'),$email,password_hash($pass,PASSWORD_DEFAULT)]);$root=dirname(CONFIG_FILE);if(!is_dir($root))mkdir($root,0755,true);$cfg="<?php\nreturn ".var_export(['site'=>['name'=>$name,'accent'=>$data['accent']??'#8b5cf6'],'db'=>['dsn'=>$dsn,'user'=>$dbu,'pass'=>$dbp],'cron_token'=>bin2hex(random_bytes(24)),'payments'=>['enabled'=>false,'provider'=>'stripe','secret'=>'','publishable'=>'']],true).";\n";file_put_contents(CONFIG_FILE,$cfg);if(!is_dir(APP_ROOT.'/storage'))mkdir(APP_ROOT.'/storage',0755,true);file_put_contents(APP_ROOT.'/storage/installed.lock',date(DATE_ATOM));unset($_SESSION['install']);header('Location: '.url('/login'));exit;}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Install GameScore</title><link rel="stylesheet" href="<?=url('/assets/app.css')?>"></head><body class="install"><main class="installer"><div class="brand"><span class="brand-mark">G</span><span>GameScore</span></div><div class="progress"><i style="width:<?=$step*25?>%"></i></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="step" value="<?=$step?>"><?php if($step===1):?><h1>Let's build your game site.</h1><p>GameScore configures itself around the kind of site you actually want. Humanity finally invented a setup wizard.</p><label>Site name<input name="site_name" value="<?=e($data['site_name']??'GameScore')?>"></label><label>Accent colour<input name="accent" value="<?=e($data['accent']??'#8b5cf6')?>"></label><?php elseif($step===2):?><h1>Choose your data sources.</h1><p>Steam News works without an API key. Additional adapters can be enabled later.</p><label class="check"><input type="checkbox" checked disabled> Steam News verified source</label><label class="check"><input type="checkbox" name="manual" value="1" checked> Manual editorial updates</label><?php elseif($step===3):?><h1>Connect your database.</h1><p>MySQL/MariaDB is the safest shared-hosting choice. No Node process. No daemon. No cloud ceremony.</p><label>Database host<input name="db_host" value="<?=e($data['db_host']??'localhost')?>"></label><label>Database name<input name="db_name" value="<?=e($data['db_name']??'gamescore')?>"></label><label>Database user<input name="db_user" value="<?=e($data['db_user']??'')?>"></label><label>Database password<input type="password" name="db_pass"></label><?php else:?><h1>Create the owner account.</h1><label>Name<input name="admin_name" value="<?=e($data['admin_name']??'Admin')?>"></label><label>Email<input type="email" name="admin_email" value="<?=e($data['admin_email']??'')?>"></label><label>Password<input type="password" name="admin_pass"></label><p class="muted">Payments start disabled. Stripe credentials can be added later in the configuration.</p><?php endif;?><button class="button primary" type="submit"><?=$step===4?'Install GameScore':'Continue'?></button></form></main></body></html>
